changeSet.sql:
select person_attribute_type_id into @healthCenterType from person_attribute_type where uuid = '8d87236c-c2cc-11de-8d13-0010c6dffd0f'; select now() into @now;
select location_id into @mostCommonVisitLocation from visit where voided = 0 group by location_id order by count(*) desc, location_id asc limit 1;
insert into person_attribute (person_id, value, person_attribute_type_id, creator, date_created, voided, uuid) select p.person_id, @mostCommonVisitLocation, @healthCenterType, 1, @now, 0, uuid() from person p inner join patient pt on pt.patient_id = p.person_id where p.voided = 0 and @mostCommonVisitLocation is not null and not exists ( select 1 from person_attribute pa where pa.person_id = p.person_id and pa.person_attribute_type_id = @healthCenterType and pa.voided = 0 );

update idgen_auto_generation_option set uuid = '78412aa5-d654-4db3-9bc4-a047348c9737' where identifier_type = (select patient_identifier_type_id from patient_identifier_type where uuid = '${patientIdentifierType.dossierNumber.uuid}') and location = (select location_id from location where uuid = '${location.uhm.uuid}') and uuid != '78412aa5-d654-4db3-9bc4-a047348c9737' limit 1;
update idgen_auto_generation_option set uuid = '1dde3c45-1114-45f5-9ea0-dc3cbc74adec' where identifier_type = (select patient_identifier_type_id from patient_identifier_type where uuid = '${patientIdentifierType.dossierNumber.uuid}') and location = (select location_id from location where uuid = '${location.cdi.uuid}') and uuid != '1dde3c45-1114-45f5-9ea0-dc3cbc74adec' limit 1;
update idgen_auto_generation_option set uuid = '3285e100-f222-4552-8957-228a97aa4b6b' where identifier_type = (select patient_identifier_type_id from patient_identifier_type where uuid = '${patientIdentifierType.dossierNumber.uuid}') and location = (select location_id from location where uuid = '${location.cange.uuid}') and uuid != '3285e100-f222-4552-8957-228a97aa4b6b' limit 1;
